css:
body { font-family: system-ui, sans-serif; padding: 1rem; background: #fff8ef; }
.dish { background: #fff; border: 2px solid #c0392b; border-radius: 12px; padding: 0.75rem; min-width: 0; overflow-wrap: anywhere; }
.dish h2 { font-size: 1rem; margin: 0 0 0.25rem; }
.price { margin: 0; font-weight: bold; color: #c0392b; }

/* Your CSS below:
   1. Make .menu a grid
   2. Three equal columns, written with repeat()
   3. A 1rem gap between the cards
   4. Make .special (the first card) span 2 columns */
.menu {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}
.special { grid-column: span 2; }
